  CONSTRAINT "/RT/ASSET_ENTRIES#FK#REPOSITORY" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID") REFERENCES "/RT/ASSET_REPOSITORIES" ("PACKAGE_ID", "REPOSITORY_ID"),
  CONSTRAINT "/RT/ASSET_ENTRIES#FK#PARENT" FOREIGN KEY ("PACKAGE_ID", "REPOSITORY_ID", "PARENT_PATH") REFERENCES "/RT/ASSET_ENTRIES" ("PACKAGE_ID", "REPOSITORY_ID", "PATH"),
  CONSTRAINT "/RT/ASSET_ENTRIES#FK#BLOB" FOREIGN KEY ("SHA256") REFERENCES "/RT/ASSET_BLOBS" ("SHA256"),
