  CONSTRAINT "/RT/ASSET_ENTRIES#CK#REPOSITORY_ID" CHECK ("REPOSITORY_ID" IS NULL OR (length("REPOSITORY_ID") <= 32)),
  CONSTRAINT "/RT/ASSET_ENTRIES#CK#PATH" CHECK ("PATH" IS NULL OR (length("PATH") <= 255)),
