  CONSTRAINT "/RT/ASSET_ENTRIES#CK#SHA256" CHECK ("SHA256" IS NULL OR (length("SHA256") <= 64)),
  CONSTRAINT "/RT/ASSET_ENTRIES#CK#SOURCE_PATH" CHECK ("SOURCE_PATH" IS NULL OR (length("SOURCE_PATH") <= 255)),
  CONSTRAINT "/RT/ASSET_ENTRIES#CK#MODIFIED_AT" CHECK ("MODIFIED_AT" IS NULL OR ("MODIFIED_AT" GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9].[0-9][0-9][0-9][0-9][0-9][0-9]Z' AND strftime('%Y-%m-%dT%H:%M:%S', substr("MODIFIED_AT", 1, 19)) IS substr("MODIFIED_AT", 1, 19)))
) STRICT;

